import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        final long MOD = 1000000007L;
        long total = 1;

        if (k == 0) {
            for (int i = 0; i < p - 1; ++i) {
                total = (total * p) % MOD;
            }
        } else {
            int[] parent = new int[p];
            int[] size = new int[p];
            for (int i = 0; i < p; i++) {
                parent[i] = i;
                size[i] = 1;
            }
            int count_components = p;

            // findParent with path compression
            Function<Integer, Integer> findParent = new Function<Integer, Integer>() {
                public Integer apply(Integer x) {
                    while (parent[x] != x) {
                        parent[x] = parent[parent[x]];
                        x = parent[x];
                    }
                    return x;
                }
            };

            // unionSets
            BiFunction<Integer, Integer, Boolean> unionSets = new BiFunction<Integer, Integer, Boolean>() {
                public Boolean apply(Integer a, Integer b) {
                    a = findParent.apply(a);
                    b = findParent.apply(b);
                    if (a.equals(b)) return false;
                    if (size[a] < size[b]) {
                        int temp = a;
                        a = b;
                        b = temp;
                    }
                    parent[b] = a;
                    size[a] += size[b];
                    count_components--;
                    return true;
                }
            };

            for (int i = 0; i < p; ++i) {
                int to = (int)((long)k * i % p);
                unionSets.apply(i, to);
            }

            if (k > 1) {
                Set<Integer> components = new HashSet<>();
                for (int i = 0; i < p; ++i) {
                    components.add(findParent.apply(i));
                }
                count_components = components.size();
            }

            for (int i = 0; i < count_components; ++i) {
                total = (total * p) % MOD;
            }
        }
        System.out.println(total);
    }
}
